globalCss:
.distill-style-article {
  max-width: 42rem;
  margin-left: auto;
  margin-right: auto;
  font-family: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  font-size: 1.0625rem;
  line-height: 1.75;
  color: #1F2933;
}
.distill-style-article p + p {
  margin-top: 1.25rem;
}
.distill-style-cite {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.68em;
  font-weight: 600;
  vertical-align: super;
  line-height: 0;
  color: #2A7AE2;
  text-decoration: none;
  cursor: pointer;
}
.distill-style-cite:hover {
  text-decoration: underline;
}
.distill-style-sidenote {
  display: block;
  margin: 1rem 0;
  padding: 0.625rem 0.875rem;
  border-left: 2px solid rgba(42, 122, 226, 0.4);
  border-radius: 0.125rem;
  background: #F3F4F6;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.8125rem;
  line-height: 1.6;
  color: #6B7280;
}
@media (min-width: 1280px) {
  .distill-style-sidenote {
    position: absolute;
    top: 0;
    right: -14rem;
    width: 12rem;
    margin: 0;
    padding: 0.5rem 0 0 0;
    border-left: none;
    border-top: 1px solid #E5E7EB;
    background: transparent;
    font-size: 0.75rem;
  }
}
.distill-style-figure {
  max-width: 56rem;
  margin: 2.5rem auto;
}
.distill-style-figcaption {
  margin-top: 0.75rem;
  padding-top: 0.5rem;
  border-top: 1px solid #E5E7EB;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.8125rem;
  line-height: 1.6;
  color: #6B7280;
}
.distill-style-table {
  width: 100%;
  border-collapse: collapse;
  border-top: 2px solid #1F2933;
  border-bottom: 2px solid #1F2933;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
}
.distill-style-table thead th {
  border-bottom: 1px solid #1F2933;
  padding: 0.5rem 0.75rem;
  text-align: left;
  font-weight: 600;
  color: #1F2933;
}
.distill-style-table tbody td {
  padding: 0.5rem 0.75rem;
  color: #1F2933;
}
.distill-style-hairline {
  border: none;
  border-top: 1px solid #E5E7EB;
}
.distill-style-smallcaps {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #6B7280;
}
